import * as fs from "node:fs";
import * as path from "node:path";
const entryId = (n: number) => "ar" + n.toString(16).padStart(6, "0");
function writeSession(ctx: any, name: string, build: (push: (entry: any, parent?: string | null) => string) => void) {
  const dir = path.dirname(ctx.sessionManager.getSessionFile());
  const lines: string[] = [JSON.stringify({ type: "session", version: 3, id: "66666666-6666-4666-8666-666666666666", timestamp: "2026-11-06T10:00:00.000Z", cwd: ctx.cwd })];
  let n = 0;
  let last: string | null = null;
  const push = (entry: any, parent: string | null | undefined = last): string => {
    const id = entryId(++n);
    lines.push(JSON.stringify({ ...entry, id, parentId: parent, timestamp: "2026-11-06T10:00:00.000Z" }));
    last = id;
    return id;
  };
  build(push);
  fs.writeFileSync(path.join(dir, name), lines.join("\n") + "\n");
}
const assistantCall = (call: any) => ({ role: "assistant", content: [call], api: "openai-completions", provider: "eq-llm", model: "eq-1",
  usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } }, stopReason: "toolUse", timestamp: 1 });
const reset = (summary: string) => ({ type: "compaction", summary, firstKeptEntryId: null, tokensBefore: 100, details: { posthorse: 1 } });
export default function (pi: any) {
  // native-host.ts countedArchive: 4096 archived user messages, a boundary in the middle, the current window
  pi.registerCommand("eq-archive", {
    description: "harness: write archive.jsonl (4096 archived HIST_NEEDLE messages)",
    handler: async (_args: string, ctx: any) => {
      writeSession(ctx, "archive.jsonl", (push) => {
        for (let i = 0; i < 4096; i++) {
          if (i === 2048) push(reset("Earlier boundary."));
          push({ type: "message", message: { role: "user", content: "HIST_NEEDLE old:" + i + ".", timestamp: i } });
        }
        push(reset("Current boundary."));
        push({ type: "message", message: { role: "user", content: "HIST_NEEDLE visible.", timestamp: 5000 } });
        for (let i = 0; i < 100; i++) push({ type: "message", message: { role: "user", content: "Current unrelated.", timestamp: 5001 + i } });
      });
    },
  });
  // native-host.ts:1143: five archived needles, a boundary, 64 unrelated 64 KiB tool calls, the visible needle
  pi.registerCommand("eq-projection", {
    description: "harness: write projection.jsonl (64 unrelated 64 KiB tool-call arguments)",
    handler: async (_args: string, ctx: any) => {
      writeSession(ctx, "projection.jsonl", (push) => {
        for (let i = 0; i < 5; i++) push({ type: "message", message: { role: "user", content: "PROJECTION_NEEDLE old:" + i + ".", timestamp: i } });
        push(reset("Earlier entries archived."));
        for (let i = 0; i < 64; i++) {
          push({ type: "message", message: assistantCall({ type: "toolCall", id: "call-" + i, name: "unrelated", arguments: { historyProjectionProbe: true, index: i, payload: "x".repeat(65536) } }) });
        }
        push({ type: "message", message: { role: "user", content: "PROJECTION_NEEDLE visible.", timestamp: 100 } });
      });
    },
  });
}
